<script setup lang="ts">
type Route='airborne'|'contact'|'food_water'|'vector'|'zoonotic'
type Intervention={id:string;nl:string;en:string;routes:Route[];effect:number;speed:number;burden:number;equity:number;evidence:number;kind:string}
const props=withDefaults(defineProps<{locale?:'nl'|'en'}>(),{locale:'nl'})
const nl=computed(()=>props.locale==='nl')
const p=reactive({route:'airborne' as Route,r0:2.5,presymptomatic:35,severity:45,icuNeed:25,capacityPressure:55,diagnostics:true,vaccine:false,treatment:false,uncertainty:55,lives:30,capacity:30,transmission:20,society:20})
const routes:{id:Route;nl:string;en:string}[]=[{id:'airborne',nl:'Lucht/respiratoir',en:'Airborne/respiratory'},{id:'contact',nl:'Direct contact',en:'Direct contact'},{id:'food_water',nl:'Voedsel/water',en:'Food/water'},{id:'vector',nl:'Vector',en:'Vector-borne'},{id:'zoonotic',nl:'Dier/omgeving',en:'Animal/environment'}]
const interventions:Intervention[]=[
 {id:'ventilation',nl:'Ventilatie en filtratie',en:'Ventilation and filtration',routes:['airborne'],effect:4.3,speed:3,burden:1.4,equity:4,evidence:4,kind:'omgeving'},
 {id:'isolation',nl:'Testen en casusisolatie',en:'Testing and case isolation',routes:['airborne','contact','food_water'],effect:4,speed:4,burden:2.1,equity:2.7,evidence:4.2,kind:'opsporing'},
 {id:'tracing',nl:'Contactonderzoek',en:'Contact tracing',routes:['airborne','contact'],effect:3.7,speed:3,burden:2.7,equity:3,evidence:3.8,kind:'opsporing'},
 {id:'protection',nl:'Respiratoire of contactbescherming',en:'Respiratory or contact protection',routes:['airborne','contact','zoonotic'],effect:3.8,speed:4.5,burden:1.8,equity:3,evidence:3.8,kind:'persoonlijk'},
 {id:'vaccination',nl:'Vaccinatie',en:'Vaccination',routes:['airborne','contact','food_water','vector','zoonotic'],effect:4.7,speed:2,burden:2,equity:4,evidence:3.5,kind:'medisch'},
 {id:'treatment',nl:'Behandeling en profylaxe',en:'Treatment and prophylaxis',routes:['airborne','contact','food_water','vector','zoonotic'],effect:4.2,speed:3.5,burden:1.6,equity:3.5,evidence:3.6,kind:'medisch'},
 {id:'healthcare',nl:'Zorgcapaciteit en personeelsbescherming',en:'Healthcare capacity and staff protection',routes:['airborne','contact','food_water','vector','zoonotic'],effect:3.6,speed:2.2,burden:2.4,equity:4.2,evidence:4,kind:'zorg'},
 {id:'source',nl:'Bron-, dier- en omgevingscontrole',en:'Source, animal and environmental control',routes:['food_water','vector','zoonotic'],effect:4.6,speed:3.2,burden:2.2,equity:3.5,evidence:4,kind:'bron'},
 {id:'support',nl:'Thuisblijf- en inkomensondersteuning',en:'Stay-home and income support',routes:['airborne','contact'],effect:3.1,speed:3.5,burden:2.5,equity:4.8,evidence:3.2,kind:'ondersteuning'},
 {id:'temporary',nl:'Tijdelijke brede contactreductie',en:'Temporary broad contact reduction',routes:['airborne','contact'],effect:4.4,speed:4.5,burden:4.8,equity:1.8,evidence:3.2,kind:'sociaal'}]
const totalWeight=computed(()=>p.lives+p.capacity+p.transmission+p.society||1)
const weight=(key:'lives'|'capacity'|'transmission'|'society')=>p[key]/totalWeight.value
const ranked=computed(()=>interventions.map(item=>{
 const routeMatch=item.routes.includes(p.route)?1:.12
 const transmissionNeed=Math.min(1.4,.35+p.r0/5+(p.presymptomatic/100)*.35)
 const healthNeed=.35+p.severity/100+p.icuNeed/180+p.capacityPressure/180
 const availability=item.id==='vaccination'?(p.vaccine?1:.05):item.id==='treatment'?(p.treatment?1:.08):(item.id==='isolation'||item.id==='tracing')?(p.diagnostics?1:.28):1
 const presymPenalty=item.id==='tracing'||item.id==='isolation'?1-p.presymptomatic/180:1
 const capacityBoost=item.id==='healthcare'?1+p.capacityPressure/100:1
 const socialPenalty=item.burden*(.4+weight('society')*2.2)
 const benefit=item.effect*routeMatch*availability*presymPenalty*capacityBoost*(transmissionNeed*weight('transmission')+healthNeed*(weight('lives')+weight('capacity'))+item.equity/5*.25)
 const confidence=.55+item.evidence/10-(p.uncertainty/100)*.28
 const score=benefit*confidence-socialPenalty*.32+item.speed*.12
 const reasons:string[]=[]
 if(routeMatch===1)reasons.push(nl.value?'past bij de transmissieroute':'matches the transmission route')
 if(item.id==='tracing'&&p.presymptomatic>45)reasons.push(nl.value?'verliest waarde door veel vroege transmissie':'loses value with extensive early transmission')
 if(item.id==='healthcare'&&p.capacityPressure>65)reasons.push(nl.value?'stijgt door druk op de zorg':'rises with healthcare pressure')
 if((item.id==='vaccination'&&!p.vaccine)||(item.id==='treatment'&&!p.treatment))reasons.push(nl.value?'is nog niet beschikbaar':'is not yet available')
 if(item.id==='temporary')reasons.push(nl.value?'heeft een hoge maatschappelijke last':'has a high societal burden')
 return{...item,score,confidence:Math.max(.15,Math.min(.95,confidence)),reasons}
 }).sort((a,b)=>b.score-a.score))
const preset=(name:'respiratory'|'ebola'|'qfever'|'food')=>{Object.assign(p,name==='respiratory'?{route:'airborne',r0:3.2,presymptomatic:45,severity:38,icuNeed:28,capacityPressure:68,diagnostics:true,vaccine:false,treatment:false,uncertainty:62}:name==='ebola'?{route:'contact',r0:1.7,presymptomatic:0,severity:92,icuNeed:45,capacityPressure:48,diagnostics:true,vaccine:true,treatment:true,uncertainty:38}:name==='qfever'?{route:'zoonotic',r0:.4,presymptomatic:0,severity:22,icuNeed:5,capacityPressure:18,diagnostics:true,vaccine:false,treatment:true,uncertainty:45}:{route:'food_water',r0:2.1,presymptomatic:15,severity:18,icuNeed:3,capacityPressure:30,diagnostics:true,vaccine:false,treatment:false,uncertainty:35})}
const routeLabel=computed(()=>routes.find(x=>x.id===p.route)![nl.value?'nl':'en'])
const packageStrength=reactive<Record<string,number>>({ventilation:70,isolation:65,tracing:35,protection:55,vaccination:0,treatment:0,temporary:0})
const policy=reactive({periodic:false,start:21,duration:21,interval:180,lockdownReduction:82,fatality:.35,hospitalRate:3,absenceThreshold:8,hospitalCapacity:0.25,funeralCapacity:35,waningDays:365,imports:2})
const packageItems=computed(()=>interventions.filter(x=>Object.prototype.hasOwnProperty.call(packageStrength,x.id)))
const setPackage=(name:'none'|'targeted'|'broad')=>Object.assign(packageStrength,name==='none'?{ventilation:0,isolation:0,tracing:0,protection:0,vaccination:0,treatment:0,temporary:0}:name==='broad'?{ventilation:80,isolation:80,tracing:55,protection:75,vaccination:p.vaccine?70:0,treatment:p.treatment?65:0,temporary:65}:{ventilation:p.route==='airborne'?70:15,isolation:p.diagnostics?65:15,tracing:p.diagnostics&&p.presymptomatic<40?55:20,protection:['airborne','contact','zoonotic'].includes(p.route)?55:15,vaccination:p.vaccine?60:0,treatment:p.treatment?55:0,temporary:0})
const setHalfYearLockdown=()=>{setPackage('none');Object.assign(policy,{periodic:true,start:21,duration:21,interval:180,lockdownReduction:82})}
const radarAxes=computed(()=>[
 {label:nl.value?'Besmettelijkheid':'Contagiousness',value:Math.min(1,p.r0/5)},
 {label:nl.value?'Vroege transmissie':'Early spread',value:p.presymptomatic/100},
 {label:nl.value?'Ernst':'Severity',value:p.severity/100},
 {label:nl.value?'Zorgbelasting':'Care burden',value:(p.icuNeed+p.capacityPressure)/200},
 {label:nl.value?'Bron/omgeving':'Source/environment',value:['food_water','vector','zoonotic'].includes(p.route)?.9:.2},
 {label:nl.value?'Onzekerheid':'Uncertainty',value:p.uncertainty/100}
])
const polar=(index:number,value:number,r=92)=>{const angle=-Math.PI/2+index*Math.PI*2/radarAxes.value.length;return`${120+Math.cos(angle)*r*value},${120+Math.sin(angle)*r*value}`}
const radarPolygon=computed(()=>radarAxes.value.map((x,i)=>polar(i,x.value)).join(' '))
const simulation=computed(()=>{
 const routeFactor:Record<Route,Record<string,number>>={airborne:{ventilation:.22,isolation:.15,tracing:.08,protection:.18,vaccination:.3,treatment:0,temporary:.32},contact:{ventilation:0,isolation:.2,tracing:.18,protection:.2,vaccination:.28,treatment:0,temporary:.3},food_water:{ventilation:0,isolation:.08,tracing:0,protection:0,vaccination:.2,treatment:0,temporary:.04},vector:{ventilation:0,isolation:0,tracing:0,protection:0,vaccination:.2,treatment:0,temporary:0},zoonotic:{ventilation:0,isolation:.05,tracing:0,protection:.18,vaccination:.18,treatment:0,temporary:.04}}
 let reduction=0
 for(const [id,intensity] of Object.entries(packageStrength)) reduction+=(routeFactor[p.route][id]||0)*intensity/100
 reduction=Math.min(.82,reduction)
 const treatmentReduction=(packageStrength.treatment||0)/100*(p.treatment ? .35 : 0)
 const vaccineSeverity=(packageStrength.vaccination||0)/100*(p.vaccine ? .3 : 0)
 const isLockdown=(day:number)=>policy.periodic&&day>=policy.start&&((day-policy.start)%Math.max(policy.interval,policy.duration))<policy.duration
 const run=(withMeasures:boolean)=>{let s=.999,i=.001,r=0,deaths=0;const infections:number[]=[];const care:number[]=[];const dailyDeaths:number[]=[];for(let day=0;day<=365;day++){const scheduled=withMeasures&&isLockdown(day)?policy.lockdownReduction/100:0;const applied=withMeasures?1-(1-reduction)*(1-scheduled):0;const effectiveR=p.r0*(1-applied);const recover=i/7;const imported=policy.imports/1_000_000;const newly=Math.min(s,i*effectiveR/7*s+imported);const waning=policy.waningDays>0?r/policy.waningDays:0;const fatal=newly*(policy.fatality/100)*(withMeasures?1-treatmentReduction-vaccineSeverity:1);s=Math.max(0,s-newly+waning);i=Math.max(0,i+newly-recover);r=Math.max(0,r+recover-waning-fatal);deaths+=fatal;infections.push(i);care.push(i*(policy.hospitalRate/100)*(withMeasures?1-treatmentReduction-vaccineSeverity:1));dailyDeaths.push(fatal*1_000_000)}return{infections,care,dailyDeaths,deaths,peakInfection:Math.max(...infections),peakCare:Math.max(...care),peakDeaths:Math.max(...dailyDeaths)}}
 const measures=run(true)
 return{baseline:run(false),measures,reduction,lockdownDays:Array.from({length:366},(_,day)=>isLockdown(day)?day:-1).filter(day=>day>=0),limits:{absence:measures.peakInfection*100>policy.absenceThreshold,hospital:measures.peakCare*100>policy.hospitalCapacity,funeral:measures.peakDeaths>policy.funeralCapacity}}
})
const linePoints=(values:number[],max:number)=>values.map((v,i)=>`${20+i/365*500},${180-v/max*145}`).join(' ')
const chartMax=computed(()=>Math.max(.01,...simulation.value.baseline.infections,...simulation.value.baseline.care)*1.08)
</script>

<template>
 <section class="response-model" data-analytics-model="pathogen-response">
  <header><p class="eyebrow">{{nl?'SCENARIOVERKENNER':'SCENARIO EXPLORER'}}</p><h2>{{nl?'De ziekte bepaalt de gereedschapskist':'The pathogen shapes the toolbox'}}</h2><p>{{nl?'Bouw een hypothetisch ziekteprofiel en zie hoe kenmerken, doelen en onzekerheid de rangorde van interventies veranderen. De uitkomst is een illustratie van beslislogica, geen medisch of beleidsadvies.':'Build a hypothetical disease profile and see how characteristics, objectives and uncertainty change the intervention ranking. The result illustrates decision logic; it is not medical or policy advice.'}}</p></header>
  <div class="presets"><span>{{nl?'Startscenario':'Starting scenario'}}</span><button @click="preset('respiratory')">{{nl?'Nieuw respiratoir virus':'Novel respiratory virus'}}</button><button @click="preset('ebola')">Ebola-achtig</button><button @click="preset('qfever')">Q-koortsachtig</button><button @click="preset('food')">{{nl?'Voedseluitbraak':'Foodborne outbreak'}}</button></div>
  <div class="model-grid">
   <div class="controls">
    <section><h3>1 · {{nl?'Ziekteprofiel':'Disease profile'}}</h3><label>{{nl?'Dominante route':'Dominant route'}}<select v-model="p.route"><option v-for="item in routes" :key="item.id" :value="item.id">{{item[nl?'nl':'en']}}</option></select></label><label>R₀ <input v-model.number="p.r0" type="range" min=".2" max="7" step=".1"><output>{{p.r0.toFixed(1)}}</output></label><label>{{nl?'Transmissie vóór symptomen':'Pre-symptomatic transmission'}}<input v-model.number="p.presymptomatic" type="range" min="0" max="80"><output>{{p.presymptomatic}}%</output></label><label>{{nl?'Ernst':'Severity'}}<input v-model.number="p.severity" type="range" min="0" max="100"><output>{{p.severity}}</output></label><label>{{nl?'IC-behoefte':'ICU need'}}<input v-model.number="p.icuNeed" type="range" min="0" max="100"><output>{{p.icuNeed}}</output></label><label>{{nl?'Druk op zorgcapaciteit':'Healthcare pressure'}}<input v-model.number="p.capacityPressure" type="range" min="0" max="100"><output>{{p.capacityPressure}}%</output></label></section>
    <section><h3>2 · {{nl?'Beschikbaar en bekend':'Available and known'}}</h3><div class="checks"><label><input v-model="p.diagnostics" type="checkbox">{{nl?'Bruikbare diagnostiek':'Usable diagnostics'}}</label><label><input v-model="p.vaccine" type="checkbox">{{nl?'Passend vaccin':'Matching vaccine'}}</label><label><input v-model="p.treatment" type="checkbox">{{nl?'Effectieve behandeling':'Effective treatment'}}</label></div><label>{{nl?'Algemene onzekerheid':'Overall uncertainty'}}<input v-model.number="p.uncertainty" type="range" min="0" max="100"><output>{{p.uncertainty}}%</output></label></section>
    <details><summary>3 · {{nl?'Doelen wegen':'Weight objectives'}}</summary><p>{{nl?'Waarden worden relatief genormaliseerd; ze hoeven niet tot 100 op te tellen.':'Values are normalised relative to one another; they need not add to 100.'}}</p><label>{{nl?'Levens en gezondheid':'Lives and health'}}<input v-model.number="p.lives" type="range" min="0" max="100"><output>{{Math.round(weight('lives')*100)}}%</output></label><label>{{nl?'Zorg toegankelijk houden':'Maintain healthcare access'}}<input v-model.number="p.capacity" type="range" min="0" max="100"><output>{{Math.round(weight('capacity')*100)}}%</output></label><label>{{nl?'Transmissie verminderen':'Reduce transmission'}}<input v-model.number="p.transmission" type="range" min="0" max="100"><output>{{Math.round(weight('transmission')*100)}}%</output></label><label>{{nl?'Ontwrichting beperken':'Limit disruption'}}<input v-model.number="p.society" type="range" min="0" max="100"><output>{{Math.round(weight('society')*100)}}%</output></label></details>
   </div>
   <div class="results"><div class="profile"><span>{{nl?'DOMINANTE ROUTE':'DOMINANT ROUTE'}}</span><strong>{{routeLabel}}</strong><span>{{nl?'ONZEKERHEID':'UNCERTAINTY'}}</span><strong>{{p.uncertainty<34?(nl?'laag':'low'):p.uncertainty<67?(nl?'middel':'moderate'):(nl?'hoog':'high')}}</strong></div><div class="radar-wrap"><div><h3>{{nl?'Ziektekompas':'Disease compass'}}</h3><p>{{nl?'De vorm vergelijkt kenmerken binnen dit scenario; verder naar buiten betekent sterker of belangrijker.':'The shape compares characteristics within this scenario; farther out means stronger or more important.'}}</p></div><svg class="radar" viewBox="0 0 240 240" role="img" :aria-label="nl?'Stergrafiek van het ziekteprofiel':'Radar chart of the disease profile'"><g v-for="level in 4" :key="level"><polygon :points="radarAxes.map((_,i)=>polar(i,level/4)).join(' ')" /></g><line v-for="(_,i) in radarAxes" :key="i" x1="120" y1="120" :x2="polar(i,1).split(',')[0]" :y2="polar(i,1).split(',')[1]"/><polygon class="radar-value" :points="radarPolygon"/><text v-for="(axis,i) in radarAxes" :key="axis.label" :x="polar(i,1.18).split(',')[0]" :y="polar(i,1.18).split(',')[1]" text-anchor="middle">{{axis.label}}</text></svg></div><h3>{{nl?'Indicatieve prioriteiten':'Indicative priorities'}}</h3><ol><li v-for="(item,index) in ranked.slice(0,6)" :key="item.id"><span>{{index+1}}</span><div><strong>{{item[nl?'nl':'en']}}</strong><small>{{item.reasons.join(' · ')|| (nl?'brede ondersteunende waarde':'broad supporting value')}}</small></div><div class="score"><i :style="{width:`${Math.max(4,Math.min(100,35+item.score*16))}%`}"></i><small>{{nl?'vertrouwen':'confidence'}} {{Math.round(item.confidence*100)}}%</small></div></li></ol><p class="why"><strong>{{nl?'Waarom kan de rangorde omslaan?':'Why can the ranking change?'}}</strong> {{nl?'Route-overeenkomst, vroege transmissie, zorgdruk en beschikbaarheid veranderen de verwachte baten. De gewichten veranderen vervolgens hoeveel maatschappelijke belasting acceptabel lijkt.':'Route match, early transmission, healthcare pressure and availability change expected benefits. The weights then change how much societal burden appears acceptable.'}}</p></div>
  </div>
  <section class="time-model">
   <div class="time-head"><div><p class="eyebrow">{{nl?'EFFECT OVER TIJD':'EFFECT OVER TIME'}}</p><h3>{{nl?'Wanneer houdt een strategie de knelpunten beheersbaar?':'When does a strategy keep bottlenecks manageable?'}}</h3></div><div class="package-buttons"><button @click="setPackage('none')">{{nl?'Geen':'None'}}</button><button @click="setPackage('targeted')">{{nl?'Gericht':'Targeted'}}</button><button @click="setPackage('broad')">{{nl?'Breed':'Broad'}}</button><button @click="setHalfYearLockdown">{{nl?'3 weken / halfjaar':'3 weeks / half-year'}}</button></div></div>
   <div class="time-grid"><div class="measure-controls"><h4>{{nl?'Doorlopend pakket':'Continuous package'}}</h4><label v-for="item in packageItems" :key="item.id"><span>{{item[nl?'nl':'en']}}</span><input v-model.number="packageStrength[item.id]" type="range" min="0" max="100"><output>{{packageStrength[item.id]}}%</output></label><p>{{nl?'Doorlopende transmissiereductie:':'Continuous transmission reduction:'}} <strong>{{Math.round(simulation.reduction*100)}}%</strong></p><details><summary>{{nl?'Periodieke lockdown':'Periodic lockdown'}}</summary><label class="check-row"><span>{{nl?'Inschakelen':'Enable'}}</span><input v-model="policy.periodic" type="checkbox"></label><label><span>{{nl?'Eerste startdag':'First start day'}}</span><input v-model.number="policy.start" type="range" min="0" max="180"><output>{{policy.start}}</output></label><label><span>{{nl?'Duur':'Duration'}}</span><input v-model.number="policy.duration" type="range" min="7" max="56"><output>{{policy.duration}}d</output></label><label><span>{{nl?'Herhalen iedere':'Repeat every'}}</span><input v-model.number="policy.interval" type="range" min="30" max="240"><output>{{policy.interval}}d</output></label><label><span>{{nl?'Contactreductie':'Contact reduction'}}</span><input v-model.number="policy.lockdownReduction" type="range" min="20" max="95"><output>{{policy.lockdownReduction}}%</output></label></details><details><summary>{{nl?'Ziekte en systeemgrenzen':'Disease and system limits'}}</summary><label><span>{{nl?'Infection fatality ratio':'Infection fatality ratio'}}</span><input v-model.number="policy.fatality" type="range" min=".05" max="3" step=".05"><output>{{policy.fatality}}%</output></label><label><span>{{nl?'Opnamerisico':'Hospitalisation risk'}}</span><input v-model.number="policy.hospitalRate" type="range" min=".2" max="15" step=".1"><output>{{policy.hospitalRate}}%</output></label><label><span>{{nl?'Grens gelijktijdig ziek':'Simultaneously ill limit'}}</span><input v-model.number="policy.absenceThreshold" type="range" min="1" max="25" step=".5"><output>{{policy.absenceThreshold}}%</output></label><label><span>{{nl?'Ziekenhuiscapaciteit':'Hospital capacity'}}</span><input v-model.number="policy.hospitalCapacity" type="range" min=".05" max="2" step=".05"><output>{{policy.hospitalCapacity}}%</output></label><label><span>{{nl?'Uitvaartcapaciteit':'Funeral capacity'}}</span><input v-model.number="policy.funeralCapacity" type="range" min="2" max="100"><output>{{policy.funeralCapacity}}</output></label></details></div>
    <div class="time-chart"><svg viewBox="0 0 540 210" role="img" :aria-label="nl?'Gesimuleerd verloop van infectiegraad en zorgbelasting':'Simulated course of infection prevalence and healthcare burden'"><rect v-for="day in simulation.lockdownDays" :key="day" class="lockdown-day" :x="20+day/365*500" y="35" :width="500/365+1" height="145"/><line x1="20" y1="180" x2="520" y2="180"/><line x1="20" y1="35" x2="20" y2="180"/><polyline class="baseline" :points="linePoints(simulation.baseline.infections,chartMax)"/><polyline class="active" :points="linePoints(simulation.measures.infections,chartMax)"/><polyline class="care" :points="linePoints(simulation.measures.care,chartMax)"/><text x="20" y="200">0</text><text x="260" y="200">180</text><text x="492" y="200">365 {{nl?'dagen':'days'}}</text></svg><div class="legend"><span class="baseline-key">{{nl?'Infectiegraad zonder maatregelen':'Infection prevalence without measures'}}</span><span class="active-key">{{nl?'Infectiegraad met strategie':'Infection prevalence with strategy'}}</span><span class="care-key">{{nl?'Ziekenhuisbehoefte':'Hospital demand'}}</span></div><div class="outcomes"><article :class="{breach:simulation.limits.absence}"><span>{{nl?'Piek gelijktijdig ziek':'Peak simultaneously ill'}}</span><strong>{{(simulation.measures.peakInfection*100).toFixed(1)}}%</strong><small>{{nl?'grens':'limit'}} {{policy.absenceThreshold}}%</small></article><article :class="{breach:simulation.limits.hospital}"><span>{{nl?'Piek ziekenhuisbehoefte':'Peak hospital demand'}}</span><strong>{{(simulation.measures.peakCare*100).toFixed(2)}}%</strong><small>{{nl?'capaciteit':'capacity'}} {{policy.hospitalCapacity}}%</small></article><article :class="{breach:simulation.limits.funeral}"><span>{{nl?'Piek sterfte':'Peak mortality'}}</span><strong>{{simulation.measures.peakDeaths.toFixed(1)}}</strong><small>{{nl?'per mln/dag · grens':'per m/day · limit'}} {{policy.funeralCapacity}}</small></article><article><span>{{nl?'Cumulatieve sterfte':'Cumulative mortality'}}</span><strong>{{Math.round(simulation.measures.deaths*1_000_000)}}</strong><small>{{nl?'per miljoen in één jaar':'per million in one year'}}</small></article></div></div></div>
   <p class="model-note">{{nl?'Didactisch SIRS-model met zeven dagen besmettelijkheid, immuniteitsafname na gemiddeld één jaar en twee geïmporteerde infecties per miljoen per dag. Een lockdown verlaagt transmissie uitsluitend tijdens de gekleurde vensters; daarna kan groei hervatten. Leeftijd, seizoenen, varianten, gedragsreacties, opnamevertraging en ligduur ontbreken. Gebruik het om hypothesen en drempels te onderzoeken, niet om Nederlands beleid achteraf te bewijzen.':'Educational SIRS model with seven infectious days, immunity waning after one year on average and two imported infections per million per day. A lockdown reduces transmission only during the shaded windows; growth may resume afterwards. Age, seasonality, variants, behavioural responses, admission delay and length of stay are omitted. Use it to investigate hypotheses and thresholds, not to prove retrospective policy claims.'}}</p>
  </section>
  <footer><p>{{nl?'Rekenmodel v0.1. Scores zijn transparante scenarioaannames, geen gekalibreerde effectschattingen. Een echte toepassing vereist pathogeenspecifiek bewijs, lokale data, verdelingseffecten, juridische en ethische toetsing, onzekerheidsanalyse en periodieke herbeoordeling.':'Model v0.1. Scores are transparent scenario assumptions, not calibrated effect estimates. Real use requires pathogen-specific evidence, local data, distributional effects, legal and ethical review, uncertainty analysis and periodic reassessment.'}}</p></footer>
 </section>
